// === Tab: element ===
class Element {
  constructor(x0, y0, r, angle) {
    this.r = r;
    this.angle = angle;
    this.x0 = x0;
    this.y0 = y0;
    this.colour = random(COLOURS);
    this.stroke = random(COLOURS);
  }

  update() {
    this.x = this.r * cos(this.angle);
    this.y = this.r * sin(this.angle);
    this.angle += 0.05;
  }

  display() {
    fill(this.colour);
    strokeWeight(2);
    stroke(this.stroke);
    rect(this.x0 + this.x, this.y0 + this.y, 30, 5);
  }
}

