const grid = [];
const columns = 20;
const rows = 20;
const waveOffset = 100;

function setup() {
  createCanvas(windowWidth, windowHeight);

  const rowSize = height / rows;
  const columnSize = width / columns;

  for (let i = 0; i < columns; i++) {
    grid[i] = [];

    for (let j = 0; j < rows; j++) {
      grid[i][j] = new Element(
        columnSize / 2 + i * columnSize,
        rowSize / 2 + j * rowSize,
        rowSize / 2,
        i * waveOffset + j * waveOffset
      );
    }
  }
};

function draw() {
  background(BACKGROUND_COLOUR);

  for (let i = 0; i < columns; i++) {
    for (let j = 0; j < rows; j++) {
      grid[i][j].update();
      grid[i][j].display();
    }
  }
};


